setRelation.example:
// server
const { Faction } = kcds.characters;
const BANDITS = 10;
const VILLAGE = 11;
const WATCH = 12;

Faction.setRelation(BANDITS, VILLAGE, 'hostile');
Faction.setRelation(BANDITS, WATCH, 'hostile');
Faction.setRelation(VILLAGE, WATCH, 'friendly');

setRelation.exampleCs:
// server
const int Bandits = 10;
const int Village = 11;
const int Watch = 12;

Faction.SetRelation(Bandits, Village, "hostile");
Faction.SetRelation(Bandits, Watch, "hostile");
Faction.SetRelation(Village, Watch, "friendly");

relation.example:
// server
if (kcds.characters.Faction.relation(npc.faction, player.faction) === 'hostile') {
  kcds.core.Chat.sendToPlayer(player, `${npc.name} draws a weapon.`);
}

relation.exampleCs:
// server
if (Faction.Relation(npc.Faction, player.Faction) == "hostile")
{
    Chat.SendToPlayer(player, $"{npc.Name} draws a weapon.");
}

relations.example:
// server
for (const { a, b, relation } of kcds.characters.Faction.relations()) {
  console.log(`${a} and ${b}: ${relation}`);
}

relations.exampleCs:
// server
foreach (var pair in Faction.Relations())
{
    Log.Info($"{pair["a"].AsInt()} and {pair["b"].AsInt()}: {pair["relation"].AsString()}");
}
